                                                context.drawImage(namespace.Resources.tooltips4Image, OFFSET0X, OFFSET5X, OFFSET4X, OFFSET1X, size.x / 2 - 2 - namespace.getTitleHeartbeat().time * 0.3, posY - namespace.getTitleHeartbeat().time * 0.1, 4 + namespace.getTitleHeartbeat().time * 0.6, 1 + namespace.getTitleHeartbeat().time * 0.2);
                                                break;
