                                                                        if (stackObjectType === namespace.StackObjectTypeEnum.RepairCrate && namespace.CommandEnum.SelectStackObject === levelHudItems[i].type) {
                                                                            player = (levelHudItems[i].direction === namespace.DirectionEnum.Left) ? levelManager.leftPlayer : levelManager.rightPlayer;
                                                                            if (levelManager.repairKits <= 0 || (!(player.stack.objects.length > 0 && player.stack.objects[0].strength < levelManager.getStackObjectStrength(player.stack.objects[0].type)))) {
                                                                                context.globalAlpha = 0.3
                                                                            }
                                                                        }
