                                                                                context.drawImage(namespace.Resources.objectsImage, OFFSET2X, OFFSET4X, OFFSET1X, OFFSET1X, levelHudItems[i].x + 0.12, levelHudItems[i].y + 0.11, levelHudItems[i].size * 0.8, levelHudItems[i].size * 0.8);
                                                                                break;
