                                                                                context.drawImage(namespace.Resources.hud1ScreenImage, OFFSET7X, OFFSET5X, OFFSET1X, OFFSET1X, levelHudItems[i].x + 0.1, levelHudItems[i].y + 0.1, levelHudItems[i].size * 0.8, levelHudItems[i].size * 0.8);
                                                                                namespace.drawNumber(context, levelManager.repairKits.toString(), levelHudItems[i].x + 0.3, levelHudItems[i].y - 0.7, 0.7);
