                                                                            context.closePath();
                                                                            context.clip();
                                                                            context.fillStyle = "rgba(0, 0, 0, 0.5)";
                                                                            var max = levelManager.getStackObjectCreationTime(buildData.stackObjectType);
                                                                            var height = (max - buildData.cooldown) * levelHudItems[i].size / max;
