    namespace.resetDisplay = function() {
        var scaleX, scaleY;
        canvas.width = resolutionX;
        canvas.height = resolutionY;
        if (fitToScreen) {
            optimalRatioX = $(window).width() / canvas.width;
            optimalRatioY = $(window).height() / canvas.height
        } else {
            scaleX = $(window).width() / canvas.width;
            scaleY = $(window).height() / canvas.height;
            optimalRatioX = optimalRatioY = Math.min(scaleX, scaleY)
        }
        canvas.style.width = resolutionX * optimalRatioX + "px";
        canvas.style.height = resolutionY * optimalRatioY + "px";
        $("canvas").center();
        if (unitCamera) {
            unitCamera.sx = 1 / scaleUnit;
            unitCamera.sy = 1 / scaleUnit;
            unitCamera.update()
        }
    };
    namespace.applyHudCameras = function() {
        context.setTransform.apply(context, unitCamera.matrix);
        context.transform.apply(context, hudCamera.matrix)
    };
    namespace.applySceneCameras = function() {
        context.setTransform.apply(context, unitCamera.matrix);
        context.transform.apply(context, primaryCamera.matrix);
        context.transform.apply(context, secondaryCamera.matrix)
    };
    namespace.applyVeryFarParallaxCameras = function() {
        context.translate(-secondaryCamera.x * 0.15, -secondaryCamera.y * 0.15)
    };
    namespace.applyFarParallaxCameras = function() {
        context.translate(-secondaryCamera.x * 0.3, -secondaryCamera.y * 0.3)
    };
    namespace.applyNearParallaxCameras = function() {
        context.translate(-secondaryCamera.x * 0.5, -secondaryCamera.y * 0.5)
    };
    namespace.applyVeryNearParallaxCameras = function() {
        context.translate(-secondaryCamera.x * 0.75, -secondaryCamera.y * 0.75)
    };
    namespace.applyHereParallaxCameras = function() {
        context.translate(-secondaryCamera.x, -secondaryCamera.y)
    };
    namespace.screenToHud = function(point) {
        var camera = new namespace.Camera();
        camera.multiply(unitCamera);
        camera.multiply(hudCamera);
        return camera.screenToCamera(point.x, point.y)
    };
    namespace.screenToScene = function(point) {
        var camera = new namespace.Camera();
        camera.multiply(unitCamera);
        camera.multiply(primaryCamera);
        camera.multiply(secondaryCamera);
        camera.translate(-secondaryCamera.x, -secondaryCamera.y);
        return camera.screenToCamera(point.x, point.y)
    };
    namespace.cancelConfirmDialog = function() {
        gamePaused = gameWasPaused;
        confirmCommand = namespace.CommandEnum.None;
        for (var u = 0; u < levelHudItems.length;) {
            if (levelHudItems[u].type === namespace.CommandEnum.ConfirmNo || levelHudItems[u].type === namespace.CommandEnum.ConfirmYes) {
                levelHudItems.splice(u, 1)
            } else {
                u += 1
            }
        }
    };
    namespace.displayMenuConfirmDialog = function() {
        if (confirmCommand === namespace.CommandEnum.None) {
            confirmCommand = namespace.CommandEnum.Menu;
            createConfirmDialog();
            gameWasPaused = gamePaused;
            gamePaused = true
        } else {
            namespace.cancelConfirmDialog()
        }
    };
    namespace.showMainScreen = function() {
        if (currentGameState !== namespace.GameStateEnum.GameIntro && currentGameState !== namespace.GameStateEnum.GameStart && (currentGameState !== namespace.GameStateEnum.GameMenu || (currentGameState === namespace.GameStateEnum.GameMenu && currentMenuType !== namespace.MenuTypeEnum.ShowMain && currentMenuType !== namespace.MenuTypeEnum.None)) && currentGameState !== namespace.GameStateEnum.GameLoading) {
            if (currentGameState !== namespace.GameStateEnum.GameMenu && currentGameState !== namespace.GameStateEnum.GameStart) {
                namespace.SoundManager.playMainMusic()
            }
            currentGameState = namespace.GameStateEnum.GameMenu;
            menuPageIndex = 0;
            gameMaxMenuSetupTime = 3;
            gameMenuSetupTime = gameMaxMenuSetupTime;
            currentMenuType = namespace.MenuTypeEnum.ShowMain;
            menuPageTime = 0;
            menuPageDirection = namespace.DirectionEnum.None
        }
    };

    function prepareGame(images) {
        var i;
        namespace.Resources.introScreenImage = images.introScreen;
        namespace.Resources.menuScreenImage = images.menuScreen;
        namespace.Resources.loadingScreenImage = images.loadingScreen;
        namespace.Resources.hud1ScreenImage = images.hud1Screen;
        namespace.Resources.hud2ScreenImage = images.hud2Screen;
        namespace.Resources.hud3ScreenImage = images.hud3Screen;
        namespace.Resources.creditsScreenImage = images.creditsScreen;
        namespace.Resources.entitiesImage = images.entities;
        namespace.Resources.tooltips1Image = images.tooltips1;
        namespace.Resources.tooltips5Image = images.tooltips5;
        namespace.Resources.unlockImage = images.unlock;
        namespace.Resources.backgroundImage1 = images.background1;
        namespace.Resources.backgroundImage2 = images.background2;
        namespace.Resources.backdrop01Image = images.backdrop1;
        namespace.Resources.backdrop02Image = images.backdrop2;
        namespace.Resources.objectsImage = images.objects;
        namespace.Resources.effectsImage = images.effects;
        showCredits = false;
        confirmCommand = namespace.CommandEnum.None;
        menuPageIndex = 0;
        menuPageTime = 0;
        menuPageDirection = namespace.DirectionEnum.None;
        currentMenuType = namespace.MenuTypeEnum.None;
        menuHudItems = [{
            type: namespace.MenuTypeEnum.Panel,
            x: 0,
            y: 0,
            width: 0,
            height: 0
        }, {
            type: namespace.MenuTypeEnum.ShowStoryMode,
            x: 0,
            y: 0,
            width: 0,
            height: 0
        }, {
            type: namespace.MenuTypeEnum.ShowSurvivalMode,
            x: 0,
            y: 0,
            width: 0,
            height: 0
        }, {
            type: namespace.MenuTypeEnum.ShowOptions,
            x: 0,
            y: 0,
            width: 0,
            height: 0
        }, {
            type: namespace.MenuTypeEnum.ShowMain,
            x: 0,
            y: 0,
            width: 0,
            height: 0
        }, {
            type: namespace.MenuTypeEnum.SelectNextPage,
            x: 0,
            y: 0,
            width: 0,
            height: 0
        }, {
            type: namespace.MenuTypeEnum.SelectPrevPage,
            x: 0,
            y: 0,
            width: 0,
            height: 0
        }, {
            type: namespace.MenuTypeEnum.ShowCredits,
            x: 0,
            y: 0,
            width: 0,
            height: 0
        }, {
            type: namespace.MenuTypeEnum.ToggleSound,
            x: 0,
            y: 0,
            width: 0,
            height: 0
        }];
        levelItemData = [];
        for (i = 0; i < savedData.levelProgress.length; i += 1) {
            levelItemData.push({
                level: i + 1,
                x: 0,
                y: 0,
                status: savedData.levelProgress[i]
            })
        }
        menuAchievementItems = [];
        for (i = 0; i < 15; i += 1) {
            menuAchievementItems.push({
                x: 0,
                y: 0
            })
        }
        menuSurvivalItems = [{
            level: 1000,
            x: 0,
            y: 0,
            status: namespace.LevelStatusEnum.Locked
        }, {
            level: 1001,
            x: 0,
            y: 0,
            status: namespace.LevelStatusEnum.Locked
        }];
        updateSurvivalLevelStatus();
        gameMaxIntroTime = 0.1;
        gameIntroTime = 0.1;
        currentGameState = namespace.GameStateEnum.GameStart;
        wasTrial = namespace.isTrialLicense()
    }

    function updateLevelStatus(wonLevelId) {
        var item, i, len = levelItemData.length,
            makeNextAvail = 0;
        for (i = 0; i < len; i += 1) {
            item = levelItemData[i];
            if (wonLevelId === item.level) {
                item.status = namespace.LevelStatusEnum.Passed;
                savedData.levelProgress[i] = item.status;
                makeNextAvail = item.level + 1
            }
            if (makeNextAvail === item.level && item.status === namespace.LevelStatusEnum.Locked && item.level <= maxStoryModeLevel) {
                item.status = namespace.LevelStatusEnum.Available;
                savedData.levelProgress[i] = item.status
            }
        }
    }

    function updateSurvivalLevelStatus() {
        for (var i = 0; i < levelItemData.length; i += 1) {
            if (levelItemData[i].level === 6 && (levelItemData[i].status === namespace.LevelStatusEnum.Passed)) {
                menuSurvivalItems[0].status = namespace.LevelStatusEnum.Available
            } else {
                if (levelItemData[i].level === 13 && (levelItemData[i].status === namespace.LevelStatusEnum.Passed)) {
                    menuSurvivalItems[1].status = namespace.LevelStatusEnum.Available
                }
            }
        }
    }

    function runGame() {
        var now = new Date().getTime(),
            elapsed = Math.min((now - (lastUpdateTime || now)) / 1000, 0.05),
            normalElapsed = elapsed;
        lastUpdateTime = now;
        window.requestAnimationFrame(runGame);
        if (slowMotionTime > 0) {
            elapsed *= slowMotionSpeed
        }
        context.setTransform(1, 0, 0, 1, 0, 0);
        if (currentGameState === namespace.GameStateEnum.GamePreLoading) {
            namespace.drawLoader(context)
        } else {
            if (currentGameState === namespace.GameStateEnum.GameMenu) {
                context.fillStyle = "rgb(129, 109, 150)"
            }
            context.clearRect(0, 0, canvas.width, canvas.height);
            if (currentGameState === namespace.GameStateEnum.GameMenu) {
                context.fillRect(0, 0, canvas.width, canvas.height)
            }
            update(elapsed, normalElapsed);
            namespace.draw(context, levelManager)
        }
    }

    function loadLevel(level) {
        var manifest;
        gamePaused = false;
        isPointerDown = false;
        confirmCommand = namespace.CommandEnum.None;
        levelManager = new namespace.levelManager(level);
        ai = new namespace.AI();
        currentGameState = namespace.GameStateEnum.GameLoading;
        if (levelManager.currentLevel > 0) {
            manifest = [{
                type: "img",
                id: "tooltips2",
                src: "assets/img/" + assetsSubFolder + "/tooltips02.png"
            }, {
                type: "img",
                id: "tooltips3",
                src: "assets/img/" + assetsSubFolder + "/tooltips03.png"
            }, {
                type: "img",
                id: "tooltips4",
                src: "assets/img/" + assetsSubFolder + "/tooltips04.png"
            }, {
                type: "img",
                id: "backdrop3",
                src: "assets/img/" + assetsSubFolder + "/backdrop03.png"
            }];
            gameLoadingData = {
                current: 0,
                total: 0
            };
            namespace.loadResources(manifest, loadScene, onLoadStep)
        }
        if (showReviewMsg === true && level === 4 && savedData.levelProgress[3] === namespace.LevelStatusEnum.Available) {
            namespace.reviewGame();
            showReviewMsg = false
        }
    }

    function loadScene(images) {
        var camera, size;
        namespace.Resources.backdrop03Image = images.backdrop3;
        namespace.Resources.tooltips2Image = images.tooltips2;
        namespace.Resources.tooltips3Image = images.tooltips3;
        namespace.Resources.tooltips4Image = images.tooltips4;
        cameraShakingTime = 0;
        slowMotionTime = 0;
        slowMotionSpeed = 0.4;
        cameraRotationSpeed = 0.3;
        wantSlowMotion = false;
        cameraTargetAngle = 0;
        if (!levelManager.primaryWeaponAssignmentDone || !levelManager.secondaryWeaponAssignmentDone || levelManager.newItem !== namespace.StackObjectTypeEnum.None) {
            cameraTargetZoom = 0.8;
            cameraTarget = {
                x: levelManager.minX + (levelManager.maxX - levelManager.minX) / 2,
                y: levelManager.maxY + 0.5
            }
        } else {
            cameraTarget = {
                x: levelManager.minX + (levelManager.maxX - levelManager.minX) / 2,
                y: levelManager.maxY - 0.7
            };
            cameraTargetZoom = 0.6
        }
        camera = new namespace.Camera();
        camera.multiply(unitCamera);
        size = camera.screenToCamera(canvas.width, canvas.height);
        primaryCamera.x = size.x / 2 - cameraTarget.x;
        primaryCamera.y = size.y / 2 - cameraTarget.y;
        secondaryCamera.angle = 0;
        secondaryCamera.sx = cameraTargetZoom;
        secondaryCamera.sy = cameraTargetZoom;
        if (levelManager.currentLevel === 1000 || levelManager.currentLevel === 1001) {
            var item, i, len = levelItemData.length;
            var level = 6;
            for (i = 0; i < len; i += 1) {
                item = levelItemData[i];
                if (item.status !== namespace.LevelStatusEnum.Passed) {
                    break
                }
                level = Math.max(level, i + 1)
            }
            createHudItems(level)
        } else {
            createHudItems()
        }
        namespace.SoundManager.playLevelMusic();
        currentGameState = namespace.GameStateEnum.GameRun
    }

